    if isinstance(v, dict):
      return v
    elif isinstance(v, list):
      return dict(v)
    else:
      raise ValueError("Invalid input type for MyList")

@dataclass(frozen=True)
class MyList:
  input: InitVar[dict[str, int] | list[tuple[str, int]]]
  value: dict[str, int] = {}

  @field_validator('value', mode='before')
  def validate_value(cls, v: dict[str, int] | list[tuple[str, int]]):
    return validate_value(v)

MyList({'a': 1, 'b': 2}) # static typing works
MyList([('a', 1), ('b', 2)]) # static typing failed
```

I'd like to achieve
1. When `__init__`, we have type `value: dict[str, int] | list[tuple[str, int]]`
2. When `my_list.value`, we have type `dict[str, int]`

This looks like https://docs.pydantic.dev/latest/integrations/visual_studio_code/#strict-errors but for custom type transform.

## Workaround
```python
@pydantic_dataclass(frozen=True)
class MyList:
  input: InitVar[dict[str, int] | list[tuple[str, int]]] = Field(init_var=True)
  value: dict[str, int] = Field(init=False)

  @field_validator('input', mode='before')
  def validate_value(cls, v: dict[str, int] | list[tuple[str, int]]):
    return validate_value(v)

  def __post_init__(self, input):
    object.__setattr__(self, 'value', input)


